void setup() {
  pinMode(MOTOR, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int tezlik = map(analogRead(POT), 0, 1023, 0, 255);

  // motor past PWM da ishga tushmaydi — "turtki" beramiz
